CREATE TABLE `migrations` (`id` text,PRIMARY KEY (`id`));
CREATE TABLE `scheduled_nets` (`id` integer PRIMARY KEY AUTOINCREMENT,`talkgroup_id` integer NOT NULL,`created_by_user_id` integer,`name` text,`description` text,`cron_expression` text,`day_of_week` integer,`time_of_day` text,`timezone` text,`duration_minutes` integer,`enabled` numeric DEFAULT true,`next_run` datetime,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime, `showcase` numeric DEFAULT false);
CREATE INDEX `idx_scheduled_nets_deleted_at` ON `scheduled_nets`(`deleted_at`);
CREATE INDEX `idx_scheduled_nets_talkgroup_id` ON `scheduled_nets`(`talkgroup_id`);
CREATE TABLE `nets` (`id` integer PRIMARY KEY AUTOINCREMENT,`talkgroup_id` integer NOT NULL,`started_by_user_id` integer,`scheduled_net_id` integer,`start_time` datetime,`end_time` datetime,`duration_minutes` integer,`description` text,`active` numeric,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime, `showcase` numeric DEFAULT false);
CREATE INDEX `idx_nets_deleted_at` ON `nets`(`deleted_at`);
CREATE INDEX `idx_nets_active` ON `nets`(`active`);
CREATE INDEX `idx_nets_talkgroup_id` ON `nets`(`talkgroup_id`);
CREATE UNIQUE INDEX idx_nets_one_active_per_tg ON nets (talkgroup_id) WHERE active = true;
CREATE TABLE `plugins` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text NOT NULL,`token_hash` blob NOT NULL,`token_created_at` datetime NOT NULL,`enabled` numeric NOT NULL DEFAULT true,`last_connected_at` datetime,`last_seen_at` datetime,`last_address` text,`session` text NOT NULL DEFAULT "",`created_at` datetime,`updated_at` datetime, `kind` text NOT NULL DEFAULT "external", `builtin` text NOT NULL DEFAULT "", `version` text NOT NULL DEFAULT "", `author` text NOT NULL DEFAULT "", `description` text NOT NULL DEFAULT "", `module_hash` blob);
CREATE UNIQUE INDEX `idx_plugins_token_hash` ON `plugins`(`token_hash`);
CREATE UNIQUE INDEX `idx_plugins_name` ON `plugins`(`name`);
CREATE TABLE `password_resets` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer NOT NULL,`token_hash` blob NOT NULL,`expires_at` datetime NOT NULL,`created_at` datetime);
CREATE INDEX `idx_password_resets_expires_at` ON `password_resets`(`expires_at`);
CREATE UNIQUE INDEX `idx_password_resets_token_hash` ON `password_resets`(`token_hash`);
CREATE INDEX `idx_password_resets_user_id` ON `password_resets`(`user_id`);
CREATE TABLE `plugin_hosts` (`id` integer PRIMARY KEY AUTOINCREMENT,`plugin_id` integer NOT NULL,`address` text NOT NULL,`reason` text NOT NULL DEFAULT "",`allowed` numeric NOT NULL DEFAULT false);
CREATE INDEX `idx_plugin_hosts_plugin_id` ON `plugin_hosts`(`plugin_id`);
CREATE TABLE `plugin_modules` (`plugin_id` integer,`hash` blob NOT NULL,`wasm` blob NOT NULL,`created_at` datetime,PRIMARY KEY (`plugin_id`));
CREATE TABLE `users` (`id` integer PRIMARY KEY AUTOINCREMENT,`callsign` text,`username` text,`password` text,`admin` numeric,`super_admin` numeric,`email` text,`approved` numeric,`suspended` numeric,`sms_storage_enabled` numeric NOT NULL DEFAULT false,`sms_storage_since` datetime,`share_positions` numeric NOT NULL DEFAULT false,`must_change_password` numeric NOT NULL DEFAULT false,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime);
CREATE INDEX `idx_users_deleted_at` ON `users`(`deleted_at`);
CREATE UNIQUE INDEX `idx_users_username` ON `users`(`username`);
CREATE UNIQUE INDEX `idx_users_callsign` ON `users`(`callsign`);
CREATE TABLE `talkgroups` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text,`description` text,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime);
CREATE INDEX `idx_talkgroups_deleted_at` ON `talkgroups`(`deleted_at`);
CREATE TABLE `repeaters` (`connected` datetime,`last_ping` datetime,`password` text,`type` text DEFAULT "mmdvm",`dialect` text,`ts1_dynamic_talkgroup_id` integer,`ts2_dynamic_talkgroup_id` integer,`owner_id` integer,`simplex_repeater` numeric,`trusted` numeric DEFAULT false,`city` text,`state` text,`country` text,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`callsign` text,`id` integer PRIMARY KEY AUTOINCREMENT,`rx_frequency` integer,`tx_frequency` integer,`tx_power` integer,`color_code` integer,`latitude` real,`longitude` real,`height` integer,`location` text,`description` text,`url` text,`software_id` text,`package_id` text,`slots` integer,`ts1_codec` text NOT NULL DEFAULT "auto",`ts2_codec` text NOT NULL DEFAULT "auto",`ts1_heard_codec` text NOT NULL DEFAULT "",`ts2_heard_codec` text NOT NULL DEFAULT "",`ts1_heard_codec2_mode` integer NOT NULL DEFAULT 0,`ts2_heard_codec2_mode` integer NOT NULL DEFAULT 0,`ts1_heard_at` datetime,`ts2_heard_at` datetime,CONSTRAINT `fk_users_repeaters` FOREIGN KEY (`owner_id`) REFERENCES `users`(`id`),CONSTRAINT `fk_repeaters_ts1_dynamic_talkgroup` FOREIGN KEY (`ts1_dynamic_talkgroup_id`) REFERENCES `talkgroups`(`id`),CONSTRAINT `fk_repeaters_ts2_dynamic_talkgroup` FOREIGN KEY (`ts2_dynamic_talkgroup_id`) REFERENCES `talkgroups`(`id`));
CREATE INDEX `idx_repeaters_deleted_at` ON `repeaters`(`deleted_at`);
CREATE TABLE `calls` (`id` integer PRIMARY KEY AUTOINCREMENT,`call_data` bytea,`stream_id` integer,`start_time` datetime,`duration` integer,`active` numeric,`user_id` integer,`repeater_id` integer,`time_slot` numeric,`group_call` numeric,`is_to_talkgroup` numeric,`to_talkgroup_id` integer,`is_to_user` numeric,`to_user_id` integer,`is_to_repeater` numeric,`to_repeater_id` integer,`destination_id` integer,`total_packets` integer,`lost_sequences` integer,`loss` real,`jitter` real,`last_frame_num` integer,`last_seq` integer,`ber` real,`rssi` real,`total_bits` integer,`total_errors` integer,`last_packet_time` datetime,`has_header` numeric,`has_term` numeric,`kind` text NOT NULL DEFAULT "voice",`sub_kind` text,`source_id` integer,`transport` text,`ingress_id` integer,`bursts` integer,`f_id` integer,`opcode` integer,`sap` integer,`data_format` text,`confirmed` numeric,`blocks` integer,`octets` integer,`bad_crc` integer,`lost_blocks` integer,`response` text,`talker_alias` text,`alias_format` text,`latitude` real,`longitude` real,`position_error` integer,`partial` numeric,`undeliverable` text,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`codec` text,`codec2_mode` integer,`sent_ambe` integer,`sent_codec2` integer,`missed_ms` integer,`transcode_busy` numeric,CONSTRAINT `fk_calls_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`),CONSTRAINT `fk_calls_repeater` FOREIGN KEY (`repeater_id`) REFERENCES `repeaters`(`id`),CONSTRAINT `fk_calls_to_talkgroup` FOREIGN KEY (`to_talkgroup_id`) REFERENCES `talkgroups`(`id`),CONSTRAINT `fk_calls_to_user` FOREIGN KEY (`to_user_id`) REFERENCES `users`(`id`),CONSTRAINT `fk_calls_to_repeater` FOREIGN KEY (`to_repeater_id`) REFERENCES `repeaters`(`id`));
CREATE INDEX `idx_calls_deleted_at` ON `calls`(`deleted_at`);
CREATE INDEX `idx_calls_source_id` ON `calls`(`source_id`);
CREATE INDEX `idx_calls_kind` ON `calls`(`kind`);
CREATE TABLE `peers` (`id` integer PRIMARY KEY AUTOINCREMENT,`last_ping` datetime,`ip` text,`port` integer,`password` text,`owner_id` integer,`ingress` numeric,`egress` numeric,`enhanced` numeric DEFAULT false,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`codec2` numeric DEFAULT false,CONSTRAINT `fk_peers_owner` FOREIGN KEY (`owner_id`) REFERENCES `users`(`id`));
CREATE INDEX `idx_peers_deleted_at` ON `peers`(`deleted_at`);
CREATE TABLE `peer_rules` (`id` integer PRIMARY KEY AUTOINCREMENT,`peer_id` integer,`direction` numeric,`subject_id_min` integer,`subject_id_max` integer,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,CONSTRAINT `fk_peer_rules_peer` FOREIGN KEY (`peer_id`) REFERENCES `peers`(`id`));
CREATE INDEX `idx_peer_rules_deleted_at` ON `peer_rules`(`deleted_at`);
CREATE TABLE `repeater_ts2_static_talkgroups` (`repeater_id` integer,`talkgroup_id` integer,PRIMARY KEY (`repeater_id`,`talkgroup_id`),CONSTRAINT `fk_repeater_ts2_static_talkgroups_repeater` FOREIGN KEY (`repeater_id`) REFERENCES `repeaters`(`id`),CONSTRAINT `fk_repeater_ts2_static_talkgroups_talkgroup` FOREIGN KEY (`talkgroup_id`) REFERENCES `talkgroups`(`id`));
CREATE TABLE `repeater_ts1_static_talkgroups` (`repeater_id` integer,`talkgroup_id` integer,PRIMARY KEY (`repeater_id`,`talkgroup_id`),CONSTRAINT `fk_repeater_ts1_static_talkgroups_repeater` FOREIGN KEY (`repeater_id`) REFERENCES `repeaters`(`id`),CONSTRAINT `fk_repeater_ts1_static_talkgroups_talkgroup` FOREIGN KEY (`talkgroup_id`) REFERENCES `talkgroups`(`id`));
CREATE TABLE `ratelimits` (`key` text,`hits` integer,`timestamp` datetime,PRIMARY KEY (`key`));
CREATE TABLE `talkgroup_ncos` (`talkgroup_id` integer,`user_id` integer,PRIMARY KEY (`talkgroup_id`,`user_id`),CONSTRAINT `fk_talkgroup_ncos_talkgroup` FOREIGN KEY (`talkgroup_id`) REFERENCES `talkgroups`(`id`),CONSTRAINT `fk_talkgroup_ncos_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `talkgroup_admins` (`talkgroup_id` integer,`user_id` integer,PRIMARY KEY (`talkgroup_id`,`user_id`),CONSTRAINT `fk_talkgroup_admins_talkgroup` FOREIGN KEY (`talkgroup_id`) REFERENCES `talkgroups`(`id`),CONSTRAINT `fk_talkgroup_admins_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `messages` (`id` integer PRIMARY KEY AUTOINCREMENT,`received_at` datetime NOT NULL,`transmission_id` integer,`source_id` integer NOT NULL,`destination_id` integer NOT NULL,`is_group` numeric NOT NULL DEFAULT false,`repeater_id` integer NOT NULL DEFAULT 0,`slot` integer NOT NULL DEFAULT 1,`transport` text,`stream_id` integer NOT NULL DEFAULT 0,`sap` integer,`format` text NOT NULL,`confirmed` numeric NOT NULL DEFAULT false,`send_sequence` integer,`fragment_seq` integer,`response` text,`bad_crc` numeric NOT NULL DEFAULT false,`text` text,`checksum_ok` numeric NOT NULL,`blocks` integer NOT NULL DEFAULT 0,`octets` integer NOT NULL DEFAULT 0,`raw` blob,`created_at` datetime,`updated_at` datetime,CONSTRAINT `fk_messages_transmission` FOREIGN KEY (`transmission_id`) REFERENCES `calls`(`id`) ON DELETE SET NULL);
CREATE INDEX `idx_messages_format` ON `messages`(`format`);
CREATE INDEX `idx_messages_transmission_id` ON `messages`(`transmission_id`);
CREATE INDEX `idx_messages_source_received` ON `messages`(`source_id`,`received_at`);
CREATE INDEX `idx_messages_destination_received` ON `messages`(`destination_id`,`received_at`);
CREATE INDEX `idx_messages_received_at` ON `messages`(`received_at`);
CREATE TABLE `user_radio_ids` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer NOT NULL,`radio_id` integer NOT NULL,`verified_at` datetime NOT NULL,`created_at` datetime,CONSTRAINT `fk_user_radio_ids_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `idx_user_radio_ids_radio_id` ON `user_radio_ids`(`radio_id`);
CREATE INDEX `idx_user_radio_ids_user_id` ON `user_radio_ids`(`user_id`);
CREATE TABLE `sessions` (`id` text,`data` text,`created_at` datetime,`updated_at` datetime,`expires_at` datetime,`user_id` integer,PRIMARY KEY (`id`));
CREATE INDEX `idx_sessions_user_id` ON `sessions`(`user_id`);
CREATE INDEX `idx_sessions_expires_at` ON `sessions`(`expires_at`);
CREATE TABLE `o_auth_grants` (`id` text,`user_id` integer,`client_id` text,`scopes` text,`created_at` datetime,`last_used_at` datetime,`revoked_at` datetime,PRIMARY KEY (`id`));
CREATE INDEX `idx_o_auth_grants_revoked_at` ON `o_auth_grants`(`revoked_at`);
CREATE INDEX `idx_o_auth_grants_client_id` ON `o_auth_grants`(`client_id`);
CREATE INDEX `idx_o_auth_grants_user_id` ON `o_auth_grants`(`user_id`);
CREATE TABLE `o_auth_codes` (`hash` text,`user_id` integer,`client_id` text,`redirect_uri` text,`scopes` text,`challenge` text,`expires_at` datetime,`used_at` datetime,`grant_id` text,PRIMARY KEY (`hash`));
CREATE INDEX `idx_o_auth_codes_expires_at` ON `o_auth_codes`(`expires_at`);
CREATE TABLE `o_auth_refresh_tokens` (`hash` text,`grant_id` text,`expires_at` datetime,`used_at` datetime,PRIMARY KEY (`hash`));
CREATE INDEX `idx_o_auth_refresh_tokens_grant_id` ON `o_auth_refresh_tokens`(`grant_id`);
CREATE TABLE `position_settings` (`radio_id` integer,`user_id` integer NOT NULL,`tracking` numeric NOT NULL DEFAULT false,`tracking_since` datetime,`interval_seconds` integer NOT NULL DEFAULT 600,`retention_hours` integer NOT NULL DEFAULT 24,`aprs` numeric NOT NULL DEFAULT false,`aprsss_id` text,`aprs_symbol` text,`aprs_comment` text,`updated_at` datetime,PRIMARY KEY (`radio_id`));
CREATE INDEX `idx_position_settings_user_id` ON `position_settings`(`user_id`);
CREATE TABLE `positions` (`id` integer PRIMARY KEY AUTOINCREMENT,`radio_id` integer NOT NULL,`latitude` real NOT NULL,`longitude` real NOT NULL,`format` text NOT NULL,`accuracy_m` real,`speed_mps` real,`heading_deg` real,`altitude_m` real,`fix_time` datetime,`received_at` datetime NOT NULL,`repeater_id` integer NOT NULL DEFAULT 0,`slot` integer NOT NULL DEFAULT 1,`service_id` integer NOT NULL DEFAULT 0);
CREATE INDEX `idx_positions_received_at` ON `positions`(`received_at`);
CREATE INDEX `idx_positions_radio_received` ON `positions`(`radio_id`,`received_at`);
CREATE TABLE "plugin_ranges"  (`id` integer PRIMARY KEY AUTOINCREMENT,`plugin_id` integer NOT NULL,`first_id` integer NOT NULL,`last_id` integer NOT NULL,CONSTRAINT `fk_plugins_ranges` FOREIGN KEY (`plugin_id`) REFERENCES `plugins`(`id`) ON DELETE CASCADE);
CREATE INDEX `idx_plugin_ranges_plugin_id` ON `plugin_ranges`(`plugin_id`);
